{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Racemic thalidomide, a close structural analogue sharing the glutarimide and imide/lactam scaffold, has absolute oral bioavailability of 80–100% in fasting healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "(S)-Thalidomide showed an absolute oral bioavailability of approximately 80% in healthy volunteers after capsule versus infusion dosing, supporting high F for the closely related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "(R)-Thalidomide showed an absolute oral bioavailability of approximately 100% in healthy volunteers, further supporting high F for the query's structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Aminoglutethimide, which shares the piperidine-2,6-dione (glutarimide) ring, has an oral bioavailability of approximately 100%, supporting high F despite lower overall structural similarity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence, thalidomide and its enantiomers, shows high absolute oral bioavailability (80–100%) in humans. The query is the 4-amino isoindolinone analogue of thalidomide, sharing the glutarimide and imide/lactam core; the amino substitution improves solubility and does not introduce a known low-F liability. Additional glutarimide-containing high-F drugs support the same direction. Therefore the query is predicted to have F ≥ 20% (high).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability study for the query molecule (lenalidomide) was retrieved; thalidomide evidence is the closest surrogate.",
    "Most thalidomide records are not formal absolute bioavailability studies with IV comparator, though enantiomer studies provide absolute estimates.",
    "The only low-F record (THU, F 10–14%) is structurally distant and has very low transferability, so it does not materially support a low prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

